-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 10: Visões — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('9c097f64-d5fc-576e-aaf3-349c536203ac', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Uma visão relacional é essencialmente:', '["Um arquivo de log.","Um índice exclusivo.","Uma transação suspensa.","Uma cópia física obrigatória.","Uma expressão relacional nomeada."]'::jsonb, 4, 'A visão constitui uma relvar derivada virtual definida por uma expressão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.1, páginas 501–505 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4470a360-7ff6-56b3-b6be-cc1a4c492ca2', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Consultar uma visão exige necessariamente armazenar previamente todas as suas linhas?', '["Não, porque visões não possuem resultado.","Sim, uma vez por usuário.","Não; sua definição pode ser expandida durante o processamento.","Sim, como requisito do modelo.","Sim, antes de qualquer inserção no banco."]'::jsonb, 2, 'Visões virtuais podem ser avaliadas a partir das relvars de origem.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.1, páginas 501–505 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6bde35af-ca51-5ef2-87bb-8781b33fba07', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Na implementação conceitual por substituição, consultar uma visão consiste em:', '["Desativar todos os predicados.","Substituir seu nome pela expressão que a define.","Renomear fisicamente todos os arquivos.","Usar apenas o último backup.","Excluir sua definição após cada leitura."]'::jsonb, 1, 'O fechamento permite integrar a expressão definidora à consulta externa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.3, páginas 511–512 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a728bce-6a8d-57a1-9fb7-dff7c4ecbbd7', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Ocultar o atributo salário em uma visão contribui principalmente para:', '["Normalizar automaticamente a tabela.","Criptografar os valores armazenados.","Garantir que salários estejam corretos.","Restringir a informação apresentada aos usuários daquela interface.","Eliminar qualquer possibilidade de acesso por outros canais."]'::jsonb, 3, 'A visão pode limitar exposição, mas segurança completa depende também dos demais privilégios.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d99f06a4-197d-5fa2-b34c-7dc4ed7a968c', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Manter uma interface de visão estável após reestruturar tabelas básicas favorece:', '["Obrigatoriedade de navegação física.","Duplicação não controlada.","Mudança automática de todas as aplicações.","Eliminação de tipos.","Independência de dados lógica."]'::jsonb, 4, 'A visão pode preservar a forma de acesso esperada pelas aplicações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('36c589f8-5114-5ed1-858e-3599b6aca301', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Dar um nome a uma consulta complexa usada em vários relatórios serve como:', '["Abreviação reutilizável e simplificação da interface.","Obrigação de copiar o resultado.","Substituição das restrições de origem.","Conversão do banco em arquivo sequencial.","Confirmação automática de transações."]'::jsonb, 0, 'A visão evita repetir a mesma expressão em vários pontos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9d89e962-a2b4-58e0-bf7e-c2df455ac664', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'O princípio de permutabilidade discutido por Date defende que aplicações não dependam indevidamente de:', '["Predicados do resultado.","Significado dos dados.","Seus requisitos de integridade.","Tipos declarados de atributos.","Uma relvar ser básica ou derivada."]'::jsonb, 4, 'O tratamento uniforme busca reduzir diferenças artificiais entre interfaces básicas e virtuais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a9c6896-74e4-5423-8390-026cafb86080', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Atualizar uma visão envolve necessariamente avaliar:', '["Somente a quantidade de índices.","Quais alterações nas relvars de origem correspondem à operação e preservam restrições.","Apenas o nome do usuário.","A velocidade da conexão, sem considerar os dados.","Somente a ordem das colunas na tela."]'::jsonb, 1, 'Atualização por visão precisa de semântica definida e efeitos válidos nas fontes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a81b0fb4-db04-5588-a885-6236f2993f69', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma visão filtra produtos com preço acima de 100. Com CHECK OPTION, inserir preço 80 pela visão deve:', '["Excluir todos os produtos baratos.","Ser aceito e automaticamente convertido para 101.","Alterar a definição da visão.","Ser rejeitado por não satisfazer a condição da visão.","Confirmar sem verificar o predicado."]'::jsonb, 3, 'CHECK OPTION impede que alterações pela visão produzam linhas fora de sua condição.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9b80e03f-9571-5924-921f-10e6e0349ea3', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Sem CHECK OPTION, uma atualização por visão pode fazer uma linha deixar de aparecer nela?', '["Sim, mas a tabela básica será sempre eliminada.","Não, porque visões não usam filtros.","Sim, somente se o banco estiver offline.","Não, toda visão possui esse controle implicitamente.","Sim, quando a alteração deixa de satisfazer seu filtro e a operação é admitida."]'::jsonb, 4, 'O desaparecimento da visão não significa necessariamente exclusão da linha básica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.6, páginas 538–542 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('06052e57-b5f0-5ed8-bed0-710721059343', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Por que uma visão de totais por setor exige cuidado ao receber atualizações?', '["Um novo total não determina por si só como distribuir alterações entre as linhas básicas.","Porque totais não podem ser consultados.","Porque agregação elimina o esquema do banco.","Porque todos os resultados agregados são índices.","Porque toda visão agregada é uma cópia física."]'::jsonb, 0, 'Atualizações precisam de correspondência definida, não de uma distribuição arbitrária dos valores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c0df41c7-b0a0-5e9a-ac4b-efad9f7ed153', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Uma visão de projeção omite um atributo obrigatório sem valor padrão. Qual dificuldade pode surgir ao inserir por ela?', '["O tipo dos atributos visíveis desaparece.","A projeção passa a ordenar fisicamente a tabela.","A inserção vira automaticamente uma exclusão.","Faltar informação necessária para construir uma tupla básica válida.","A unicidade deixa de poder ser declarada."]'::jsonb, 3, 'As restrições das fontes continuam aplicáveis às operações realizadas pela visão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7f8bb274-37cc-58f9-91dd-60f1f3362d23', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma visão junta pedidos e clientes. Alterar um atributo de cliente pode afetar a apresentação de vários pedidos porque:', '["Cada linha da visão é uma cópia independente obrigatória.","Pedidos e clientes devem ter chaves idênticas.","Várias tuplas da junção podem referir-se ao mesmo cliente.","Junções sempre duplicam registros básicos.","Visões não preservam correspondências."]'::jsonb, 2, 'A multiplicidade de correspondências precisa ser considerada na semântica de atualização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('79ef33a0-b787-574a-8423-4a4a21d0d316', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Excluir uma linha de uma visão de junção deve significar apagar todas as entidades envolvidas?', '["Sim, sempre em todas as tabelas.","Sim, pois junção é produto físico.","Não; os efeitos dependem de regras de atualização e restrições bem definidas.","Não, porque uma visão de junção não pode ser lida.","Sim, inclusive entidades não relacionadas."]'::jsonb, 2, 'Não se deve deduzir uma política de exclusão apenas da aparência do resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dcbe675f-2ab2-5406-bcea-75e7d34e8183', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Fácil', 'Qual diferença caracteriza um snapshot em relação a uma visão virtual comum?', '["Ele substitui a chave primária.","Ele mantém uma cópia materializada de dados de um instante ou atualização.","Ele é necessariamente atualizado a cada leitura.","Ele representa apenas permissões.","Ele não possui resultado consultável."]'::jsonb, 1, 'Snapshots introduzem armazenamento de resultados e uma política de renovação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.5, páginas 535–537 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5c7bf455-61d6-595d-aed0-73cce33bcb49', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma cópia materializada é renovada apenas à noite. Durante o dia ela pode:', '["Eliminar todas as transações.","Refletir um estado anterior ao das fontes.","Impedir alterações nas tabelas básicas.","Garantir dados mais recentes que as fontes.","Tornar irrelevante seu horário de renovação."]'::jsonb, 1, 'A atualidade depende do mecanismo e da periodicidade de manutenção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.5, páginas 535–537 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('31946474-3ae6-5990-af96-c05d7b25b4a3', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual compromisso surge ao materializar um resultado de consulta?', '["Eliminar todos os custos de atualização.","Garantir ausência de redundância.","Ganhar desempenho de leitura ao custo de armazenamento e manutenção.","Tornar inúteis as consultas às fontes.","Dispensar qualquer estratégia de renovação."]'::jsonb, 2, 'Materialização mantém informação derivada que precisa ser administrada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.5, páginas 535–537 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0d9fc9b1-63ca-5ebc-a89d-c8ff8808f670', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Descartar uma visão virtual implica necessariamente excluir os dados das tabelas que ela consulta?', '["Não; remove-se a definição da visão, respeitadas as dependências aplicáveis.","Sim, mas apenas dados com valores numéricos.","Não, pois visões não possuem definições.","Sim, sempre todas as linhas.","Sim, porque a visão possui exclusivamente os dados."]'::jsonb, 0, 'Definição derivada e conteúdo das fontes são objetos distintos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.6, páginas 538–542 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a67916fa-b28a-57ac-b355-8b78215b8b51', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Uma visão V2 consulta V1, que consulta uma relvar básica. Conceitualmente, a busca pode:', '["Exigir que V1 seja uma cópia física.","Consultar apenas o nome de V2 sem expressão.","Transformar V2 em chave estrangeira.","Expandir sucessivamente as definições até as fontes.","Ignorar o filtro de V1."]'::jsonb, 3, 'Composição e substituição permitem construir interfaces derivadas em camadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.3, páginas 511–512 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8a30bd17-a0ae-5b5d-ba6d-95d14f443eae', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Uma aplicação consulta somente uma visão com nomes estáveis. Renomear colunas básicas pode ser transparente se:', '["A definição da visão for ajustada preservando seu contrato externo.","O usuário adivinhar os novos nomes.","A visão também mudar todos os nomes expostos.","Todas as linhas forem duplicadas.","Os tipos forem removidos."]'::jsonb, 0, 'Preservar o contrato da visão pode isolar a aplicação da reestruturação subjacente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
